<script setup lang="ts">
import {ref,watch,onMounted,nextTick,onBeforeUnmount} from 'vue';import {useRoute,useRouter,onBeforeRouteLeave} from 'vue-router';import EventPicker from '../components/EventPicker.vue';import {api,catalog,statusName,duration,displayTime,loadCatalog,session} from '../lib/api';
interface Row{id:string;title:string;type:string;status:string;public_number:string;contact_name:string;contact_uid:string;duration_seconds:number;updated_at:string;planned:number}
const route=useRoute(),router=useRouter(),data=ref<{items:Row[];total:number;page:number}>({items:[],total:0,page:1}),q=ref(String(route.query.q??'')),status=ref(String(route.query.status??'')),planned=ref(String(route.query.planned??'')),page=ref(Math.max(1,Number(route.query.page)||1)),error=ref(''),loading=ref(false),filtersOpen=ref(false);let ready=false,sequence=0,timer:ReturnType<typeof setTimeout>;
const scrollKey=()=>`usagi-review-scroll:${session.user?.id}:${route.fullPath}`;
async function load(){if(!ready)return;const seq=++sequence;loading.value=true;error.value='';try{await router.replace({query:{event:catalog.eventId,...(q.value?{q:q.value}:{}),...(status.value?{status:status.value}:{}),...(planned.value?{planned:planned.value}:{}),page:String(page.value)}});if(!ready||seq!==sequence||route.path!=='/admin/submissions')return;const result=await api<typeof data.value>('/api/admin/submissions?'+new URLSearchParams({event:catalog.eventId,q:q.value,status:status.value,planned:planned.value,page:String(page.value)}));if(seq===sequence)data.value=result;}catch(e){if(seq===sequence)error.value=(e as Error).message;}finally{if(seq===sequence)loading.value=false;}}
watch([()=>catalog.eventId,status,planned],()=>{if(!ready)return;page.value=1;void load();},{flush:'sync'});watch(q,()=>{clearTimeout(timer);timer=setTimeout(()=>{page.value=1;void load();},300);});watch(page,()=>void load());
onMounted(async()=>{try{await loadCatalog();if(catalog.events.some(e=>e.id===route.query.event))catalog.eventId=String(route.query.event);ready=true;await load();await nextTick();try{window.scrollTo(0,Number(sessionStorage.getItem(scrollKey()))||0);}catch{}}catch(e){error.value=(e as Error).message;}});
onBeforeRouteLeave(()=>{ready=false;++sequence;clearTimeout(timer);try{sessionStorage.setItem(scrollKey(),String(window.scrollY));}catch{}return true;});onBeforeUnmount(()=>clearTimeout(timer));
</script>
<template><div class="page"><header class="page-head"><h1>投稿审核</h1><EventPicker/></header><section class="paper"><button type="button" class="mobile-filter-toggle" :aria-expanded="filtersOpen" @click="filtersOpen=!filtersOpen">筛选 · {{ status?statusName(status):'全部状态' }}{{ q?' · '+q:'' }}{{ planned?' · '+(planned==='yes'?'已编排':'未编排'):'' }}</button><div class="filters" :class="{'filters-open':filtersOpen}"><label>搜索<input v-model="q" type="search" placeholder="节目名、负责人或 UID"></label><label>审核状态<select v-model="status"><option value="">全部状态</option><option value="pending">待审核</option><option value="approved">已通过</option><option value="rejected">已驳回</option></select></label><label>编排状态<select v-model="planned"><option value="">全部</option><option value="yes">已编排</option><option value="no">未编排</option></select></label></div><p v-if="error" role="alert" class="alert error">{{ error }}</p><p v-if="loading" role="status" class="hint">正在读取投稿…</p><div class="table-wrap"><table class="submission-table" :aria-busy="loading"><thead><tr><th>节目</th><th>负责人</th><th>时长</th><th>状态</th><th>最近更新</th><th>操作</th></tr></thead><tbody><tr v-for="r in data.items" :key="r.id"><td class="submission-title"><strong>{{ r.title }}</strong><small>{{ r.public_number }} · {{ r.type }}</small></td><td data-label="负责人">{{ r.contact_name }}<small class="mono">UID {{ r.contact_uid }}</small></td><td data-label="时长">{{ duration(r.duration_seconds) }}</td><td data-label="状态"><span class="badge" :class="r.status">{{ statusName(r.status) }}</span><small v-if="r.planned">已加入节目单</small></td><td data-label="最近更新">{{ displayTime(r.updated_at) }}</td><td><RouterLink class="button" :to="{path:'/admin/submissions/'+r.id,query:{return:route.fullPath}}">查看投稿 →</RouterLink></td></tr></tbody></table></div><div v-if="!loading&&!data.items.length" class="empty"><h3>没有符合条件的投稿</h3><p>可调整筛选条件，或等待作品提交。</p></div><div class="toolbar"><small>共 {{ data.total }} 份投稿</small><div class="inline"><button :disabled="loading||page<=1" @click="page--">上一页</button><span>{{ page }}</span><button :disabled="loading||page*20>=data.total" @click="page++">下一页</button></div></div></section></div></template>
<style scoped>
.mobile-filter-toggle{display:none}.submission-table td{overflow-wrap:anywhere}
@media(max-width:760px){.mobile-filter-toggle{display:block;width:100%;margin-bottom:14px;white-space:normal}.filters{display:none;padding:0 0 16px}.filters.filters-open{display:flex}.filters label{flex-basis:100%}.submission-table,.submission-table tbody,.submission-table tr,.submission-table td{display:block;width:100%}.submission-table thead{display:none}.submission-table tr{border:1px solid var(--line);border-radius:10px;padding:14px;margin:0 0 16px}.submission-table td{padding:7px 0;border:0;font-size:14px}.submission-table td[data-label]::before{content:attr(data-label)'：';color:var(--muted)}.submission-table td small{display:inline;margin-left:8px}.submission-table .submission-title{font-size:17px}.submission-table .submission-title small{display:block;margin:6px 0}.submission-table .button{display:block;margin-top:8px;min-height:44px}.table-wrap{overflow:visible}}
</style>
